#include <stdio.h>

typedef struct {
    int x;
    int y;
} Point;

Point make_point(int x, int y) {
    Point p;
    p.x = x;
    p.y = y;
    return p;
}

int point_x(Point p) {
    return p.x;
}

int point_y(Point p) {
    return p.y;
}

