def make_point(x, y):
    return {"x": x, "y": y}

def point_x(p):
    return p["x"]

def point_y(p):
    return p["y"]

a = make_point(3, 4)
b = make_point(7, 8)
mx = (point_x(a) + point_x(b)) // 2
